def icon(n, large=False):
 return f'<svg class="en-icon{" en-icon--large" if large else ""}" viewBox="0 0 24 24" aria-hidden="true">{icons[n]}</svg>'
(DS/'icons.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg">'+''.join(f'<symbol id="{n}" viewBox="0 0 24 24">{s}</symbol>' for n,s in icons.items())+'</svg>',encoding='utf-8')

def luminance(h):
 vals=[int(h[i:i+2],16)/255 for i in (1,3,5)]
 vals=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in vals]
 return sum(a*b for a,b in zip(vals,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([luminance(colors[a]),luminance(colors[b])]);return (y+.05)/(x+.05)
pairs=[('ink','canvas'),('text-secondary','canvas'),('surface','olive'),('olive','sage'),('danger','danger-soft'),('warning','warning-soft'),('info','info-soft'),('border-control','surface'),('olive','canvas')]
ratios=[{'foreground':a,'background':b,'ratio':round(contrast(a,b),2),'minimum':3 if a=='border-control' else 4.5} for a,b in pairs]
assert all(r['ratio']>=r['minimum'] for r in ratios)
(DS/'contraste.json').write_text(json.dumps(ratios,indent=2),encoding='utf-8')

swatches=''.join(f'<div class="swatch"><div style="background:{colors[n]}"></div><strong>{label}</strong><span>{colors[n]}</span><small>{usage}</small></div>' for n,label,usage in [('canvas','Marfim','Fundo principal'),('olive','Oliva','Ação e identidade'),('ink','Carvão','Texto principal'),('sage','Sálvia','Seleção e sucesso'),('surface','Papel','Superfícies'),('champagne','Champanhe','Detalhe decorativo')])
